'use strict';
/* All content is bundled below. No fetch, tracking, fonts or external assets. */
const DATA=window.REVISION_DATA;
const CONFIG=DATA.configuration;
const LESSONS=DATA.lessons, QUIZ=DATA.questions;
const LESSON_BY_ID=Object.fromEntries(LESSONS.map(l=>[l.id,l]));
const QUESTIONS=Object.fromEntries(QUIZ.map(q=>[q.id,q]));
const THEMES=CONFIG.themes;
const KEY='ma-revision:'+CONFIG.examId+':v'+CONFIG.storageVersion;
const $=s=>document.querySelector(s);
const all=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({version:CONFIG.storageVersion,examId:CONFIG.examId,read:[],answers:{},lesson:LESSONS[0].id,large:false,session:null,history:[],pace:CONFIG.variantPolicy.defaultPace,difficulty:'auto',pathId:CONFIG.defaultQuizPath||'1',lastDraws:{},draws:{},migration:null});
let state=fresh(),canSave=true,view='home',quizLanding=false,quizChoices=false,activeReading=null;
const renderResource=id=>id?(DATA.assets[id]||''):'';
/* Local learning evidence: help stays visible; it is never proof of unaided work outside this page. */
function freshMeta(){return {hints:0,tutorial:false,errors:0,unknown:0,lesson:false,skipped:false,legacy:false,external:false};}
function variantsFor(qi){return DATA.variants?.[qi]||[];}
function findVariant(qi,key){return variantsFor(qi).find(q=>q.variantId===key)||{...QUESTIONS[qi],variantId:'base',level:1};}
function questionAt(s,pos){if(s.questions?.[pos])return s.questions[pos];const qi=s.ids[pos],q=findVariant(qi,s.variants?.[pos]),order=s.orders?.[pos]||q.o.map((_,i)=>i);return {...q,variant:q.variantId,o:order.map(i=>q.o[i]),a:order.indexOf(q.a)};}
function activeQuestion(qi){const s=state.session;return s&&s.ids[s.pos]===qi?questionAt(s,s.pos):QUESTIONS[qi];}
function hasHelp(m){return m.hints>0||m.tutorial||m.errors>0||m.lesson||m.skipped||m.legacy||m.external;}
function normalizeMeta(m){const n=freshMeta();if(m&&typeof m==='object'){for(const k of ['hints','errors','unknown'])n[k]=Number.isInteger(m[k])&&m[k]>=0?Math.min(m[k],999):0;for(const k of ['tutorial','lesson','skipped','legacy','external'])n[k]=m[k]===true;}for(const k of ['draft','developmentText','selfReview'])if(typeof m?.[k]==='string')n[k]=m[k];if(m?.development===true)n.development=true;if(Array.isArray(m?.rubricChecked))n.rubricChecked=m.rubricChecked.filter(Number.isInteger);if(Array.isArray(m?.selectedIds))n.selectedIds=m.selectedIds.filter(x=>typeof x==='string');return n;}
function validHistory(h){return h&&typeof h.id==='string'&&typeof h.date==='string'&&!Number.isNaN(Date.parse(h.date))&&['choice','written','practice'].includes(h.mode)&&typeof h.label==='string'&&Array.isArray(h.rows)&&h.rows.length>0&&h.rows.every(r=>r&&typeof r.qi==='string'&&typeof r.correct==='boolean'&&typeof r.independent==='boolean'&&r.meta&&typeof r.meta==='object');}
function loadLearning(raw){
state.history=Array.isArray(raw?.history)?raw.history.filter(validHistory).slice(-CONFIG.historyLimit).map(h=>({...h,rows:h.rows.map(r=>{const meta=normalizeMeta(r.meta);return {...r,meta,independent:r.correct&&!hasHelp(meta)};})})):[];
state.pace=['auto','steady'].includes(raw?.pace)?raw.pace:CONFIG.variantPolicy.defaultPace;
state.difficulty=raw?.difficulty==='auto'||(raw?.difficulty==='mixed'&&CONFIG.mixedDifficultyLabel)||Object.hasOwn(CONFIG.difficultyLabels||{},raw?.difficulty)?raw.difficulty:(state.pace==='steady'?'1':'auto');
state.pathId=Object.hasOwn(CONFIG.quizPaths||{},raw?.pathId)?raw.pathId:(CONFIG.defaultQuizPath||'1');
state.lastDraws=raw?.lastDraws&&typeof raw.lastDraws==='object'?Object.fromEntries(Object.entries(raw.lastDraws).filter(([k,v])=>typeof v==='string')):{};
state.draws=raw?.draws&&typeof raw.draws==='object'?Object.fromEntries(Object.entries(raw.draws).filter(([k,v])=>Number.isInteger(v)&&v>=0)):{};
state.answers={};state.history.forEach(h=>h.rows.forEach(r=>{if(QUESTIONS[r.qi])state.answers[r.qi]=r.independent;}));
if(state.session){const s=state.session;s.choices.forEach((c,i)=>{if(QUESTIONS[s.ids[i]])state.answers[s.ids[i]]=c===questionAt(s,i).a&&!hasHelp(s.meta[i]);});}
}
function evidence(qi,mode){return state.history.filter(h=>h.mode===mode).flatMap(h=>h.rows.filter(r=>r.qi===qi));}
function recommendedLevel(qi,mode){const p=CONFIG.variantPolicy;if(state.difficulty==='mixed'){const configured=Object.keys(CONFIG.difficultyLabels||{'1':'Simple'}).map(Number).filter(Number.isFinite).sort((a,b)=>a-b),target=configured[(state.draws['mixed|'+mode]||0)%configured.length]||1,levels=availableLevels(qi);return Math.max(...levels.filter(l=>l<=target),levels[0]);}if(state.difficulty!=='auto'){const levels=availableLevels(qi);return Math.max(...levels.filter(l=>l<=Number(state.difficulty)),levels[0]);}if(state.pace==='steady'||p.mode==='fixed')return 1;const rows=evidence(qi,mode);let level=1;for(let target=2;target<=p.maxLevel;target++){const last=rows.filter(r=>r.level===target-1).slice(-p.successes);if(last.length>=p.successes&&last.every(r=>r.independent)&&new Set(last.map(r=>r.variant)).size>=Math.min(p.distinctVariants,new Set([...(target===2?[variantSignature(QUESTIONS[qi])]:[]),...variantsFor(qi).filter(q=>q.level===target-1).map(variantSignature)]).size||1))level=target;else break;}const recent=rows.slice(-p.fallbackFailures);if(recent.length===p.fallbackFailures&&recent.every(r=>!r.independent))level=Math.max(1,Math.min(level,recent.at(-1).level-1));return variantsFor(qi).some(q=>q.level===level)?level:1;}
function availableLevels(qi){return [...new Set([1,...variantsFor(qi).map(q=>q.level)])].sort((a,b)=>a-b);}
function variantSignature(q){return JSON.stringify([q.q,q.writtenPrompt,[...q.o].sort(),q.matching||null]);}
function pickVariant(qi,mode){const level=recommendedLevel(qi,mode),base={...QUESTIONS[qi],variantId:'base',level:1};let pool=[...(level===1?[base]:[]),...variantsFor(qi).filter(q=>q.level===level)];pool=[...new Map(pool.map(q=>[variantSignature(q),q])).values()];if(!pool.length)pool=[base];const key=qi+'|'+mode+'|'+level,lastKey=qi+'|'+mode;let n=state.draws[key]||0,q=pool[n%pool.length];if(pool.length>1&&variantSignature(q)===state.lastDraws[lastKey])q=pool[(++n)%pool.length];state.draws[key]=n+1;state.lastDraws[lastKey]=variantSignature(q);if(state.difficulty==='mixed')state.draws['mixed|'+mode]=(state.draws['mixed|'+mode]||0)+1;return q.variantId;}
function sessionLabel(s){return CONFIG.quizPaths?.[s.pathId]?.label||CONFIG.legacyPathLabels?.[s.label]||s.label;}

function shuffledOrder(count){const a=Array.from({length:count},(_,i)=>i);for(let i=count-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function beginSession(ids,label,mode='choice',check=false,planned=null){stopReading();quizLanding=false;if(!ids.length||ids.some(id=>!QUESTIONS[id]))return;quizChoices=mode==='choice';const variants=ids.map((i,index)=>planned?.[index]?.variantId||pickVariant(i,mode)),questions=ids.map((id,i)=>{const q=findVariant(id,variants[i]),order=shuffledOrder(q.o.length);return {...structuredClone(q),variant:q.variantId,o:order.map(n=>q.o[n]),a:order.indexOf(q.a),...(q.type==='multi-select'?{multiSelect:{...structuredClone(q.multiSelect),options:shuffledOrder(q.multiSelect.options.length).map(i=>structuredClone(q.multiSelect.options[i]))}}:{})};});state.session={id:Date.now()+'-'+Math.random().toString(36).slice(2,10),examId:CONFIG.examId,contentVersion:CONFIG.contentVersion,ids:[...ids],choices:[],written:[],pos:0,label,mode,check,variants,questions,meta:ids.map(freshMeta)};save();show('quiz');}
function markLessonHelp(){const s=state.session;if(s&&s.pos<s.ids.length&&s.choices.length===s.pos){s.meta[s.pos].lesson=true;save();}}
function requestHint(tutorial=false){const s=state.session;if(!s||s.check||s.choices.length>s.pos)return;const typed=$('#written-answer')?.value||'';const m=s.meta[s.pos];if(tutorial){m.tutorial=true;m.hints=Math.max(1,m.hints);}else m.hints=Math.max(1,m.hints);save();renderQuiz();if(!quizChoices)$('#written-answer').value=typed;const box=$('#hint-box');box.tabIndex=-1;box.focus();}
function tryChoice(n){const s=state.session;if(!s||s.choices.length>s.pos)return;const q=questionAt(s,s.pos),m=s.meta[s.pos];if(!Number.isInteger(n)||n<0||n>=q.o.length)return;stopReading();if(n!==q.a){m.errors++;save();if(m.errors===1&&!s.check){const typed=$('#written-answer')?.value||'';renderQuiz();if(!quizChoices)$('#written-answer').value=typed;$('#choice-help').textContent='Ce premier essai n’est pas juste. Tu peux réessayer ou demander un indice. Le bilan gardera la trace de ce nouvel essai.';$('#choice-help').tabIndex=-1;$('#choice-help').focus();return;}}finishChoice(n);}
function finishChoice(n){const s=state.session;if(!s||s.choices.length>s.pos)return;const qi=s.ids[s.pos],q=questionAt(s,s.pos);s.choices.push(n);state.answers[qi]=n===q.a&&!hasHelp(s.meta[s.pos]);save();renderQuiz();$('#feedback').focus();}
function skipToExplanation(){const s=state.session;if(!s||s.choices.length>s.pos)return;s.meta[s.pos].skipped=true;stopReading();finishChoice(-1);}
function sessionReport(s){const rows=s.ids.map((qi,i)=>{const q=questionAt(s,i),meta=normalizeMeta(s.meta[i]),correct=s.choices[i]===q.a;return {qi,slotId:s.slotIds?.[i]||qi,assessedObjectiveId:s.pathObjectives?.[i]||null,objectiveIds:q.objectiveIds||[],inventoryIds:q.inventoryIds||[],level:q.level||1,variant:q.variantId||'base',questionVersion:q.fingerprint,lessonId:q.lessonId,topic:q.t,correct,independent:correct&&!hasHelp(meta),meta};});return {id:s.id,date:new Date().toISOString(),examId:CONFIG.examId,contentVersion:s.contentVersion,label:s.label,pathId:s.pathId||null,mode:s.mode,check:s.check===true,rows};}
function counts(h){const rows=h.rows.filter(r=>!r.meta.development);return {alone:rows.filter(r=>r.independent).length,aided:rows.filter(r=>r.correct&&!r.independent).length,review:rows.filter(r=>!r.correct).length,total:rows.length,development:h.rows.filter(r=>r.meta.development).length};}
function saveCompleted(s){let old=state.history.find(h=>h.id===s.id);if(old)return old;const h=sessionReport(s);state.history.push(h);state.history=state.history.slice(-CONFIG.historyLimit);save();return h;}
function scoreMarkup(h){const c=counts(h);return `<div class="stats"><div class="stat"><strong>${c.alone} / ${c.total}</strong><span>sans aide dans le site, au premier essai</span></div><div class="stat"><strong>${c.aided}</strong><span>réussies avec aide ou nouvel essai</span></div><div class="stat"><strong>${c.review}</strong><span>à revoir</span></div></div>${c.development?`<p>${c.development} réponse(s) à développer comparée(s) au corrigé, hors du score automatique.</p>`:''}`;}
function cohort(h){return h.mode+'|'+h.check+'|'+h.rows.map(r=>r.qi+':'+r.level+':'+(r.questionVersion||'legacy')).sort().join(',');}
function historyMarkup(){const rows=state.history.slice(-CONFIG.historyDisplayLimit).reverse();if(!rows.length)return '<p>Aucune série terminée depuis cette mise à jour. Les anciennes notes ne précisaient pas l’aide utilisée.</p>';const last=rows[0],prev=state.history.slice(0,-1).reverse().find(h=>cohort(h)===cohort(last));let trend='';if(prev){const now=counts(last),before=counts(prev);trend=`<p>Pour les mêmes notions, le même mode et les mêmes degrés de difficulté : <b>${before.alone}/${before.total} → ${now.alone}/${now.total}</b> sans aide au premier essai.</p>`;}return trend+rows.map(h=>{const c=counts(h),levels=[...new Set(h.rows.map(r=>r.level))].sort().join(', ');return `<div class="example"><b>${escapeHTML(sessionLabel(h))}</b><p class="small">${new Date(h.date).toLocaleString(CONFIG.locale)} · ${h.mode==='practice'?'Quiz':h.mode==='written'?'Ancien quiz écrit':'Choix'}${h.check?' · reprise sans indice':''}</p><p><b>${c.alone}/${c.total} sans aide au premier essai</b> · ${c.aided} avec aide ou nouvel essai · ${c.review} à revoir${c.development?' · '+c.development+' développement(s) autoévalué(s), hors score':''}</p><p class="small">${h.rows.filter(r=>r.meta.hints).length} question(s) avec indice · ${h.rows.filter(r=>r.meta.tutorial).length} avec tutoriel · ${h.rows.filter(r=>r.meta.lesson).length} avec retour à la leçon</p></div>`;}).join('');}
function exportHistory(){const content=JSON.stringify({format:'ma-revision-backup-v3',examId:CONFIG.examId,exportedAt:new Date().toISOString(),state},null,2);const url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=CONFIG.examId+'-progression.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function correctionPicture(qi,q){return renderResource(q.feedbackResource);}
function softenWritten(s){return normalizeWritten(s).replace(/^(?:je pense que |je crois que )?(?:c est |la reponse est |ce sont )/,'').replace(/^(?:un |une |le |la |les |du |de la |des )/,'').trim();}
function editOne(a,b){if(Math.abs(a.length-b.length)>1)return false;let i=0,j=0,n=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;}else{if(++n>1)return false;if(a.length>=b.length)i++;if(b.length>=a.length)j++;}}return n+(a.length-i)+(b.length-j)<=1;}
function writtenAssessment(qi,text){const q=activeQuestion(qi),g=q.grading||{},n=softenWritten(text);if(g.type==='formula')return assessFormula(q,text);if(g.type==='matching')return assessMatching(q,text);if(g.rejectNegative&&/(^|\s)-\s*\d/.test(text))return 'wrong';if(!n)return 'unknown';const accepted=q.accepted.map(softenWritten);if(accepted.includes(n))return 'correct';if(phraseEquivalent(q,text))return 'correct';
if(g.type==='unordered-terms'){let raw=normalizeWritten(text);for(const prefix of g.prefixes||[])if(raw.startsWith(normalizeWritten(prefix)+' ')){raw=raw.slice(normalizeWritten(prefix).length+1);break;}const words=raw.split(' ').filter(w=>!(g.ignore||[]).includes(w));const groups=g.groups.map(group=>group.map(normalizeWritten));if(words.length===groups.length&&groups.every(group=>words.some(w=>group.some(term=>wordEquivalent(term,w,g)))))return 'correct';return words.every(w=>groups.some(group=>group.some(term=>wordEquivalent(term,w,g))))?'wrong':'unknown';}
if(/\b(?:pas|non|sans|jamais|aucun)\b/.test(n)||/\d/.test(n))return writtenWrong(qi,text)?'wrong':'unknown';
if(q.o.some((o,i)=>i!==q.a&&softenWritten(o)===n))return 'wrong';const safe=(g.safeTypos||[]).map(softenWritten);return safe.some(a=>a.length>=6&&editOne(a,n))?'correct':'unknown';}
function validSession(s){return s&&s.examId===CONFIG.examId&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.every(id=>typeof id==='string')&&(new Set(s.ids).size===s.ids.length||(Array.isArray(s.slotIds)&&s.slotIds.length===s.ids.length&&s.slotIds.every(id=>typeof id==='string')&&new Set(s.slotIds).size===s.slotIds.length))&&Array.isArray(s.questions)&&s.questions.length===s.ids.length&&s.questions.every((q,i)=>q&&q.id===s.ids[i]&&Array.isArray(q.o)&&q.o.length>=2&&Number.isInteger(q.a)&&q.a>=0&&q.a<q.o.length&&Array.isArray(q.accepted))&&Array.isArray(s.choices)&&s.choices.length<=s.ids.length&&s.choices.every((c,n)=>Number.isInteger(c)&&c>=-1&&c<s.questions[n].o.length)&&Number.isInteger(s.pos)&&s.pos>=0&&s.pos<=s.ids.length&&(s.choices.length===s.pos||s.choices.length===s.pos+1)&&Array.isArray(s.meta)&&s.meta.length===s.ids.length;}
function migrateLegacy(raw){const m=CONFIG.legacyImport;if(!m||!raw||raw.version!==m.version)return null;const out=fresh();out.read=(raw.read||[]).map(i=>m.lessonIds[i]).filter(Boolean);out.lesson=m.lessonIds[raw.lesson]||LESSONS[0].id;out.large=raw.large===true;out.pace=raw.pace||out.pace;out.history=(raw.history||[]).map(h=>({...h,examId:CONFIG.examId,rows:(h.rows||[]).map(r=>({...r,qi:m.questionIds[r.qi],meta:normalizeMeta(r.meta)})).filter(r=>r.qi)}));
for(const [k,v] of Object.entries(raw.draws||{})){let match=k.match(/^(\d+)-(choice|written)-(\d+)$/);if(match){const n=Number(match[1]),id=m.questionIds[n];if(id)out.draws[id+'|'+match[2]+'|'+match[3]]=v;else if(m.lessonIds[n-m.lessonRoundOffset])out.draws['lesson|'+m.lessonIds[n-m.lessonRoundOffset]]=v;}}
const s=raw.session;if(s&&Array.isArray(s.ids)&&s.ids.every(i=>m.questionIds[i])){const ids=s.ids.map(i=>m.questionIds[i]);const session={...s,examId:CONFIG.examId,contentVersion:'legacy',ids,id:s.id||Date.now()+'-legacy',mode:s.mode==='written'?'written':'choice',label:s.label||'Quiz',meta:s.ids.map((_,i)=>s.meta?.[i]?normalizeMeta(s.meta[i]):{...freshMeta(),legacy:i<s.choices.length}),questions:ids.map((id,i)=>{const q=findVariant(id,s.variants?.[i]),order=s.orders?.[i]||q.o.map((_,j)=>j);return {...structuredClone(q),variant:q.variantId,o:order.map(n=>q.o[n]),a:order.indexOf(q.a)};})};if(validSession(session))out.session=session;}
out.migration={from:m.key,at:new Date().toISOString()};return out;}
function restore(raw){if(!raw||raw.examId!==CONFIG.examId||raw.version!==CONFIG.storageVersion)return false;state=fresh();state.read=Array.isArray(raw.read)?[...new Set(raw.read.filter(id=>typeof id==='string'))]:[];state.lesson=LESSON_BY_ID[raw.lesson]?raw.lesson:LESSONS[0].id;state.large=raw.large===true;state.migration=raw.migration||null;state.session=validSession(raw.session)?raw.session:null;if(state.session)state.session.meta=state.session.meta.map(normalizeMeta);loadLearning(raw);return true;}
try{const saved=localStorage.getItem(KEY);if(saved){restore(JSON.parse(saved));}else if(CONFIG.legacyImport){const raw=JSON.parse(localStorage.getItem(CONFIG.legacyImport.key));const migrated=migrateLegacy(raw);if(migrated)restore(migrated);}localStorage.setItem(KEY,JSON.stringify(state));}catch(e){canSave=false;}
function importProgress(file){const reader=new FileReader();reader.onload=()=>{try{const backup=JSON.parse(reader.result);let raw=backup.state;if(backup.format==='revision-history-v1'&&CONFIG.legacyImport){raw=migrateLegacy({version:CONFIG.legacyImport.version,history:backup.history});}if(!raw||raw.examId!==CONFIG.examId)throw Error('Cette sauvegarde ne correspond pas à cet examen.');const previous=structuredClone(state);if(!restore(raw))throw Error('Format de sauvegarde incompatible.');const imported=state;state=previous;state.history=[...new Map([...previous.history,...imported.history].map(h=>[h.id,h])).values()].sort((a,b)=>Date.parse(a.date)-Date.parse(b.date)).slice(-CONFIG.historyLimit);state.read=[...new Set([...previous.read,...imported.read])];if(!state.session)state.session=imported.session;loadLearning(state);save();show('home');announce('Sauvegarde importée pour cet examen.');}catch(e){announce(e.message);}};reader.readAsText(file);}

function save(){try{localStorage.setItem(KEY,JSON.stringify(state));canSave=true;}catch(e){canSave=false;}saveNote();}
function saveNote(){$('#save-note').textContent=canSave?'✓ Progression enregistrée sur cet appareil.':'Progression conservée pendant cette ouverture seulement : le navigateur ne permet pas de l’enregistrer.';}
function announce(t){$('#announce').textContent=t;}
function focusHeading(container){let h=container.querySelector('h2, h3, legend');if(h){h.tabIndex=-1;h.focus();}}
function show(name,focus=true){stopReading();if(name==='learn')markLessonHelp();view=name;all('main > section').forEach(s=>s.hidden=s.id!==name);all('nav button').forEach(b=>{if(b.dataset.view===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(name==='home')renderHome();if(name==='learn')renderLesson();if(name==='quiz')renderQuiz();if(focus)focusHeading($('#'+name));window.scrollTo(0,0);}
all('nav button').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.view==='quiz')quizLanding=true;show(b.dataset.view);}));
function button(label,fn,cls=''){const b=document.createElement('button');b.textContent=label;b.className=cls;b.addEventListener('click',fn);return b;}
function options(selected,extra=''){return extra+Object.entries(THEMES).map(([k,v])=>`<option value="${k}" ${selected===k?'selected':''}>${v}</option>`).join('');}
function readCount(){return state.read.filter(id=>LESSON_BY_ID[id]).length;}
function renderHome(){const correct=Object.values(state.answers).filter(Boolean).length;let next=LESSONS.find(l=>!state.read.includes(l.id))?.id||state.lesson;$('#home').innerHTML=`<div class="panel hero"><div class="eyebrow">Un petit pas à la fois</div><h2>Une idée. Un essai.<br>Une chose de plus retenue.</h2><p class="lead">${escapeHTML(CONFIG.intro||'Choisis une leçon, puis réponds aux exercices par écrit ou avec des choix. Quelques minutes suffisent pour commencer.')}</p><div class="actions" id="home-actions"></div></div><div class="panel"><h2>Mes petits pas</h2><div class="stats"><div class="stat"><strong>${readCount()} / ${LESSONS.length}</strong><span>leçons lues</span></div><div class="stat"><strong>${QUIZ.length-Object.keys(state.answers).length}</strong><span>questions à découvrir</span></div><div class="stat"><strong>${correct} / ${QUIZ.length}</strong><span>notions réussies sans aide au dernier essai</span></div></div><p class="small">Lire et savoir répondre sont des étapes différentes. Tu peux toujours revoir une notion.</p><label for="lesson-progress" class="small">Leçons lues</label><progress id="lesson-progress" max="${LESSONS.length}" value="${readCount()}"></progress><div class="path" id="path"></div><details id="history-details"><summary>Mon historique et mes progrès</summary>${historyMarkup()}<button id="export-history">Exporter mon historique</button><label class="small" for="import-history">Importer une sauvegarde de cet examen</label><input id="import-history" type="file" accept="application/json"><p class="small">Les ${CONFIG.historyLimit} dernières séries sont conservées dans ce navigateur; les ${CONFIG.historyDisplayLimit} plus récentes sont affichées. L’export est une copie de sauvegarde à conserver. Effacer les données du navigateur efface cet historique.</p></details></div><div class="note"><b>Une routine toute simple</b><p>1. Une leçon · 2. Ses exercices · 3. Une révision des erreurs.<br>Demain, reviens sur ce qui était difficile. Fais une pause quand tu en as besoin.</p></div>`;$('#export-history').onclick=exportHistory;$('#import-history').onchange=e=>{if(e.target.files[0])importProgress(e.target.files[0]);};$('#home-actions').append(button(readCount()?'Continuer mon parcours':CONFIG.labels.start||'Commencer mon parcours',()=>openLesson(next),'primary'),button(state.session?'Reprendre mon quiz':'Aller au quiz final',()=>{if(state.session){prepareStructuredResume();quizLanding=false;save();show('quiz');}else {quizLanding=true;show('quiz');}}));$('#home-actions').append(button('Choisir le quiz final',()=>{quizLanding=true;show('quiz');},'quiet'));LESSONS.forEach((l,i)=>{const b=button('',()=>openLesson(l.id));b.innerHTML=`<span class="number">${i+1}</span><span>${l.title}${l.reference?`<small style="display:block">Fascicule : ${escapeHTML(l.reference)}</small>`:''}</span>${state.read.includes(l.id)?'<span class="done">✓ Lue</span>':''}`;$('#path').append(b);});}
function openLesson(id){if(!LESSON_BY_ID[id])return;state.lesson=id;save();show('learn');}
function renderLesson(){const i=state.lesson,l=LESSON_BY_ID[i],position=LESSONS.findIndex(x=>x.id===i);$('#learn').innerHTML=`<label class="picker-label" for="lesson-picker">Choisir une leçon</label><select class="picker" id="lesson-picker">${LESSONS.map((x,j)=>`<option value="${x.id}" ${i===x.id?'selected':''}>${j+1}. ${x.title}${x.reference?` — fascicule ${escapeHTML(x.reference)}`:''}${state.read.includes(x.id)?' — lue':''}</option>`).join('')}</select><article class="paper"><div class="eyebrow">Leçon ${position+1} sur ${LESSONS.length} · ${THEMES[l.theme]}</div><h2>${l.title}</h2>${l.reference?`<p class="small">📖 Fascicule du professeur : <strong>${escapeHTML(l.reference)}</strong>${l.pages?` · pages ${escapeHTML(l.pages)}`:''}</p>`:''}<div class="actions"><button id="read-lesson" type="button">🔊 Lire la leçon</button><button id="stop-lesson" type="button" disabled>Arrêter la lecture</button></div><p id="lesson-reading-status" role="status" class="small"></p><div class="lesson-body">${l.overview||''}<div class="note">${l.core}</div>${renderResource(l.afterCoreResource)}<div class="example"><h3>Un exemple</h3><p>${l.example}</p></div>${renderResource(l.afterExampleResource)}${(l.parts||[]).length?`<h3>Les étapes de cette leçon</h3><p class="small">Chaque étape fait partie de la matière à revoir. Les sections restent ouvertes pour suivre la lecture.</p>${l.parts.map((part,n)=>`<details open class="lesson-step"><summary>${n+1}. ${escapeHTML(part.title)}</summary><div>${part.body}${renderResource(part.resourceId)}</div></details>`).join('')}`:''}${l.takeaway||''}<details open><summary>Un peu plus loin</summary><p>${l.more}</p></details></div>${l.activityId?'<div id="activity"></div>':''}<section class="recall"><h3>Mini-quiz de la leçon</h3><p>${Math.min(CONFIG.miniQuizSize,lessonQuestions(i).length)} questions ${CONFIG.lessonQuizMode==='practice'?'avec lecture audio':'à choix'}. Les séries alternent les questions de cette leçon.</p><div class="actions" id="lesson-actions"></div></section><div class="actions" id="lesson-nav"></div></article>`;$('#lesson-picker').onchange=e=>openLesson(e.target.value);$('#lesson-actions').append(button(state.read.includes(i)?'✓ Leçon lue — annuler':'Marquer cette leçon comme lue',e=>{state.read=state.read.includes(i)?state.read.filter(x=>x!==i):[...state.read,i];save();e.currentTarget.textContent=state.read.includes(i)?'✓ Leçon lue — annuler':'Marquer cette leçon comme lue';announce(state.read.includes(i)?'Leçon marquée comme lue.':'Leçon retirée des leçons lues.');},'warm'),button('Je fais le mini-quiz ('+Math.min(CONFIG.miniQuizSize,lessonQuestions(i).length)+' questions)',()=>startLessonQuiz(i),'primary'));if(sessionLesson(state.session)===i&&state.session.pos<state.session.ids.length)$('#lesson-actions').append(button('Continuer mon mini-quiz',()=>{quizLanding=false;show('quiz');},'primary'));if(lessonQuestions(i).length>CONFIG.miniQuizSize)$('#lesson-actions').append(button('Toutes les questions de cette leçon ('+lessonQuestions(i).length+')',()=>startLessonQuiz(i,true),'quiet'));if(position>0)$('#lesson-nav').append(button('← Leçon précédente',()=>openLesson(LESSONS[position-1].id)));if(position<LESSONS.length-1)$('#lesson-nav').append(button('Leçon suivante →',()=>openLesson(LESSONS[position+1].id),'primary'));else $('#lesson-nav').append(button('Choisir un quiz',()=>show('quiz'),'primary'));if(l.activityId)renderActivity(l.activityId);keepSectionsOpen($('#learn'));setupReading({mode:'practice',pos:0},{},[l.title,l.core,l.example,...(l.parts||[]).map(p=>p.title+'. '+p.body),l.more].map(plainSpeech),['#read-lesson','#stop-lesson','#lesson-reading-status']);}



function lessonQuestions(id){return QUIZ.filter(q=>q.lessonId===id).map(q=>q.id);}
function startLessonQuiz(id,all=false){let ids=lessonQuestions(id),size=CONFIG.miniQuizSize;if(!all&&ids.length>size){const key='lesson|'+id,round=state.draws[key]||0;state.draws[key]=round+1;ids=Array.from({length:size},(_,j)=>ids[(round*size+j)%ids.length]);}if(startQuiz(ids,'Leçon '+(LESSONS.findIndex(l=>l.id===id)+1)+' · '+LESSON_BY_ID[id].title,CONFIG.lessonQuizMode||'choice')){state.session.originLessonId=id;save();renderQuiz();}}
function renderActivity(id,selected){const activity=DATA.activities.find(a=>a.id===id);if(!activity)return;const item=activity.items.find(x=>x.id===(selected||activity.defaultItemId))||activity.items[0];$('#activity').innerHTML=`<div role="group" aria-label="${escapeHTML(activity.label)}" class="gallery-buttons" id="activity-options"></div><div id="activity-content" aria-live="polite">${renderResource(item.resourceId)}</div>`;activity.items.forEach(x=>{const b=button(x.label,()=>{renderActivity(id,x.id);$('#activity-options').children[activity.items.findIndex(t=>t.id===x.id)].focus();announce(x.description);});b.setAttribute('aria-label',x.description);b.setAttribute('aria-pressed',x.id===item.id);$('#activity-options').append(b);});}


function normalizeWritten(text){return String(text).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,' ').replace(/,/g,'.').replace(/[^a-z0-9.]+/g,' ').replace(/\.(?!\d)/g,' ').replace(/\s+/g,' ').trim();}
function writtenCorrect(qi,text){return writtenAssessment(qi,text)==='correct';}
function writtenWrong(qi,text){const n=normalizeWritten(text),q=activeQuestion(qi);if(q.o.some((o,i)=>i!==q.a&&normalizeWritten(o)===n))return true;return q.grading?.numeric===true&&/^\d+(?:\.\d+)?(?: [a-z ]+)?$/.test(n);}
function shortList(theme='all',mode='choice'){const priority=i=>{const histories=state.history.filter(h=>h.mode===mode&&h.rows.some(r=>r.qi===i));const last=histories.at(-1);if(!last)return [1,0];const row=last.rows.find(r=>r.qi===i);if(!row.independent)return [0,Date.parse(last.date)];const time=Date.parse(last.date);return [Date.now()-time>=86400000?2:3,time];};return QUIZ.map(q=>q.id).filter(i=>theme==='all'||QUESTIONS[i].t===theme).sort((a,b)=>{const x=priority(a),y=priority(b);return x[0]-y[0]||x[1]-y[1]||a.localeCompare(b);}).slice(0,CONFIG.miniQuizSize);}
function startQuiz(ids,label,mode='choice'){if(state.session?.kind==='complete'&&state.session.pos<state.session.ids.length){quizLanding=true;show('quiz');announce('Un parcours complet est en cours. Reprends-le ou termine cette série avant de choisir un autre quiz.');return false;}beginSession(ids,label,mode);return true;}
function renderQuiz(){stopReading();if(quizLanding||!state.session){quizMenu();return;}const s=state.session;quizChoices=s.mode==='choice';if(s.pos>=s.ids.length){quizResult();return;}if(CONFIG.pauseBetweenBatches===true&&s.kind==='complete'&&s.pos>0&&s.pos%batchSize()===0&&(s.checkpointAck||0)<s.pos){renderCheckpoint();return;}const qi=s.ids[s.pos],q=questionAt(s,s.pos),m=s.meta[s.pos],answered=s.choices.length>s.pos;quizChoices=usesChoices(s,q);if(CONFIG.lessonQuizMode){const origin=sessionLesson(s);all('nav button').forEach(b=>{if(b.dataset.view===(origin?'learn':'quiz'))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}if(q.responseType==='development'){renderDevelopment(s,q,m,answered);return;}
$('#quiz').innerHTML=`<article class="paper"><div class="row spread"><span class="pill">${escapeHTML(sessionLabel(s))}</span><span class="small">Question ${s.pos+1} sur ${s.ids.length}</span></div><progress aria-label="Questions terminées" max="${s.ids.length}" value="${s.choices.length}"></progress>${s.check?'<p class="small">Reprise sans indice : une question à la fois, sans chronomètre. Tu peux toujours demander à voir l’explication.</p>':''}<div class="actions"><button id="read-question" type="button">🔊 Lire la question${quizChoices?' et les choix':''}</button><button id="stop-reading" type="button" disabled>Arrêter la lecture</button></div><p id="reading-status" role="status" class="small"></p><form id="question-form"><fieldset><legend tabindex="-1">${escapeHTML(quizChoices?q.q:q.writtenPrompt)}</legend>${renderResource(q.promptResource)}${q.type==='matching'?matchingMarkup(q,quizChoices,answered):''}${q.type==='multi-select'&&quizChoices?multiMarkup(q,m,answered):''}${!answered&&!quizChoices?'<label for="written-answer">Ma réponse</label><input id="written-answer" type="text" inputmode="decimal" autocomplete="off" style="width:100%;font:inherit;padding:12px;border:2px solid var(--line);border-radius:12px" aria-describedby="written-help"><p id="written-help" class="small">Écris le résultat dans l’unité indiquée dans la question. La virgule ou le point décimal sont acceptés.</p>':''}${quizChoices&&q.type!=='matching'&&q.type!=='multi-select'?`<div>${q.o.map((o,i)=>`<label class="radio ${answered&&i===q.a?'correct':answered&&i===s.choices[s.pos]?'incorrect':''}"><input type="radio" name="choice" value="${i}" ${answered&&i===s.choices[s.pos]?'checked':''} ${answered?'disabled':''}><span><b>${i+1}.</b> ${escapeHTML(o)}${answered&&i===q.a?' — ✓ Bonne réponse':answered&&i===s.choices[s.pos]?' — À revoir':''}</span></label>`).join('')}</div>`:''}</fieldset>${answered?'':`<button id="verify" class="primary" type="submit">Vérifier ma réponse</button>`}<p id="choice-help" role="status" class="small"></p></form>${!answered?`<div class="actions" id="help-actions"></div><div id="hint-box" ${m.hints||m.tutorial?'':'hidden'} class="note"><h3>${m.tutorial?'On avance par étapes':'Un indice'}</h3><p>${escapeHTML(m.tutorial?q.tutorial:q.hint)}</p><p class="small">Cette aide sera indiquée dans ton bilan. Demander de l’aide fait partie de l’apprentissage.</p></div>${m.errors?'<p class="small">Un essai précédent n’était pas juste. Une réussite maintenant sera indiquée « après un nouvel essai ».</p>':''}<details><summary>J’ai utilisé une autre aide</summary><p class="small">Un adulte, un autre site ou une explication m’a aidé pour cette question.</p><button id="declare-help">${m.external?'✓ Aide indiquée':'L’indiquer dans mon bilan'}</button></details>`:''}<div id="feedback" ${answered?'':'hidden'}></div><div id="quiz-actions" class="actions"></div><button id="pause-quiz" class="quiet">${sessionLesson(s)?'Retour à la leçon':'Retour au menu du quiz final'}</button><p class="small" style="margin-top:16px">Tu peux faire une pause. Tes essais et tes indices restent enregistrés.</p></article>`;
setupReading(s,q);if(!answered&&!quizChoices){$('#written-answer').value=m.draft||'';$('#written-answer').oninput=e=>{m.draft=e.target.value;save();};}
$('#pause-quiz').onclick=()=>{const lesson=sessionLesson(s);if(lesson){openLesson(lesson);return;}quizLanding=true;save();renderQuiz();focusHeading($('#quiz'));};
if(!answered){$('#question-form').onsubmit=e=>{e.preventDefault();if(s.choices.length>s.pos)return;if(quizChoices&&q.type==='multi-select'){submitMulti(q,m);}else if(quizChoices&&q.type==='matching'){const values=q.matching.items.map(item=>[item.id,$('#match-'+item.id).value]);if(values.some(([id,value])=>!value)){$('#choice-help').textContent='Choisis un terme pour chaque définition.';return;}const ok=values.every(([id,value])=>q.matching.items.find(x=>x.id===id).answerId===value);tryChoice(ok?q.a:(q.a+1)%q.o.length);}else if(quizChoices){const input=$('input[name=choice]:checked');if(!input){$('#choice-help').textContent='Choisis une réponse pour continuer.';return;}tryChoice(Number(input.value));}else{const text=$('#written-answer').value;if(!text.trim()){$('#choice-help').textContent='Écris une réponse courte.';return;}const outcome=s.mode==='practice'?assessNumber(q,text):writtenAssessment(qi,text);if(outcome==='unknown'){m.unknown++;save();$('#choice-help').textContent='Je ne suis pas certain de comprendre cette formulation. Ce n’est pas compté comme faux. Écris le résultat dans l’unité demandée, demande un indice ou consulte l’explication.';return;}if(!s.written.includes(s.pos))s.written.push(s.pos);tryChoice(outcome==='correct'?q.a:(q.a+1)%q.o.length);}};
if(!s.check){$('#help-actions').append(button(m.hints?'Revoir l’indice':'Un indice',()=>requestHint(false)));if(m.hints)$('#help-actions').append(button('Le tutoriel, étape par étape',()=>requestHint(true)));}
$('#help-actions').append(button('Je ne sais pas — voir l’explication',skipToExplanation,'quiet'));$('#declare-help').onclick=()=>{m.external=true;save();$('#declare-help').textContent='✓ Aide indiquée';};
}else{const ok=s.choices[s.pos]===q.a,alone=ok&&!hasHelp(m);$('#feedback').className='feedback'+(ok?' good':'');$('#feedback').tabIndex=-1;$('#feedback').innerHTML=`<h2 style="font-size:1.2rem">${m.skipped?'Regardons la méthode.':ok?'✓ Tu as trouvé.':'On reprend cette idée ensemble.'}</h2><p class="small">${alone?'Réussite sans aide dans le site, au premier essai.':ok?'Réussite avec aide ou après un nouvel essai.':'Cette notion sera proposée à nouveau.'}</p><p><b>Réponse attendue :</b> ${escapeHTML(quizChoices&&q.type==='multi-select'?q.multiSelect.options.filter(o=>q.multiSelect.correctIds.includes(o.id)).map(o=>o.label).join(', '):quizChoices?q.o[q.a]:q.accepted[0])}</p><p>${escapeHTML(q.e)}</p>${correctionPicture(qi,q)}${q.type==='multi-select'&&quizChoices?multiFeedback(q,m):''}`;setupCorrectionReading(s,q);$('#quiz-actions').append(button(s.pos+1===s.ids.length?'Voir mon bilan':'Question suivante →',()=>{s.pos++;save();renderQuiz();focusHeading($('#quiz'));},'primary'),button('Revoir la leçon',()=>openLesson(lessonForQuestion(qi))));}}
/* Native reading; corrections become readable only when revealed. */
function setupCorrectionReading(s,q){
 const development=q.responseType==='development',choice=usesChoices(s,q);
 const answer=choice&&q.type==='multi-select'?q.multiSelect.options.filter(o=>q.multiSelect.correctIds.includes(o.id)).map(o=>o.label).join(', '):choice?q.o[q.a]:q.accepted[0];
 const parts=development?[q.e,...(q.rubric||[])]:['Réponse attendue : '+answer,q.e];
 $('#feedback').innerHTML+='<div class="actions"><button id="read-correction" type="button">🔊 Lire la bonne réponse et l’explication</button><button id="stop-correction" type="button" disabled>Arrêter la lecture du corrigé</button></div><p id="correction-reading-status" role="status" class="small"></p>';
 setupReading(s,q,parts.map(plainSpeech),['#read-correction','#stop-correction','#correction-reading-status']);
}
function keepSectionsOpen(root){
 root?.querySelectorAll?.('details').forEach(d=>{d.open=true;d.ontoggle=()=>{if(!d.open)d.open=true;};});
}
// Word ranges are attached to existing text only; answer controls keep their handlers.
function readingTokens(text){return [...String(text).matchAll(/[\p{L}\p{N}]+/gu)].map(m=>({text:m[0].toLocaleLowerCase('fr'),start:m.index,end:m.index+m[0].length}));}
function prepareReadingHighlight(root){
 if(!root||!document.createTreeWalker)return null;
 const nodes=[],walker=document.createTreeWalker(root,4);
 for(let n=walker.nextNode();n;n=walker.nextNode()){
  if(!n.parentElement?.closest('button,select,textarea,input,script,style,svg,[hidden],[role="status"]')&&n.textContent.trim())nodes.push(n);
 }
 const words=[],spans=[];
 for(const node of nodes){
  const fragment=document.createDocumentFragment();let pos=0;
  for(const match of node.textContent.matchAll(/\S+/gu)){
   fragment.append(document.createTextNode(node.textContent.slice(pos,match.index)));
   const span=document.createElement('span');span.className='reading-word';span.textContent=match[0];fragment.append(span);spans.push(span);
   for(const token of readingTokens(spokenText(match[0])))words.push({text:token.text,span});
   pos=match.index+match[0].length;
  }
  fragment.append(document.createTextNode(node.textContent.slice(pos)));node.replaceWith(fragment);
 }
 let active=[];
 const clear=()=>{active.forEach(span=>span.classList.remove('reading-current'));active=[];};
 return {
  locate(text){
   const tokens=readingTokens(text);let skip=tokens[0]?.text==='choix'&&/^\d+$/.test(tokens[1]?.text||'')?1:0;
   const target=tokens.slice(skip);if(!target.length)return [];
   for(let i=0;i<=words.length-target.length;i++)if(target.every((t,j)=>t.text===words[i+j].text))return tokens.map((t,j)=>({...t,span:j<skip?null:words[i+j-skip].span}));
   return [];
  },
  show(tokens,index=null){clear();const matches=index===null?tokens:tokens.filter(t=>index>=t.start&&index<t.end);active=[...new Set(matches.map(t=>t.span).filter(Boolean))];active.forEach(span=>span.classList.add('reading-current'));},
  clear,
  dispose(){clear();for(const span of spans)if(span.parentNode){const parent=span.parentNode;span.replaceWith(document.createTextNode(span.textContent));parent.normalize();}}
 };
}
function stopReading(){const current=activeReading;activeReading=null;if(current){current.highlight?.dispose();current.cancelled=true;try{window.speechSynthesis?.cancel();}catch(e){}const stop=current.stop||$('#stop-reading');if(stop)stop.disabled=true;const start=current.start||$('#read-question');if(start)start.disabled=false;if(current.status)current.status.textContent='Lecture arrêtée.';}}
function readingParts(s,q){const choice=usesChoices(s,q),parts=[choice?q.q:q.writtenPrompt];if(q.audioDescription)parts.push(q.audioDescription);if(q.type==='multi-select'&&choice){parts.push(...q.multiSelect.options.map((o,i)=>'Choix '+(i+1)+'. '+o.label));}else if(q.type==='matching'){parts.push(...q.matching.items.map(i=>i.id+'. '+i.label),...q.matching.terms.map(t=>t.id+'. '+t.label));}else if(choice)parts.push(...q.o.map((o,i)=>'Choix '+(i+1)+'. '+o));return parts;}
function setupReading(s,q,providedParts=null,ids=['#read-question','#stop-reading','#reading-status']){const start=$(ids[0]),stop=$(ids[1]),status=$(ids[2]),synth=window.speechSynthesis,API=window.SpeechSynthesisUtterance;if(!synth||!API){start.disabled=true;status.textContent='La lecture à voix haute n’est pas disponible dans ce navigateur.';return;}start.onclick=()=>{stopReading();const root=ids[0]==='#read-lesson'?$('#learn'):ids[0]==='#read-correction'?$('#feedback'):$('#quiz');if(ids[0]==='#read-lesson')keepSectionsOpen(root);const reading={cancelled:false,index:0,parts:(providedParts||readingParts(s,q)).map(spokenText),start,stop,status,session:s,pos:s.pos};reading.highlight=prepareReadingHighlight(root);activeReading=reading;start.disabled=true;stop.disabled=false;status.textContent='Lecture en cours…';const next=()=>{if(activeReading!==reading||reading.cancelled)return;if(reading.index>=reading.parts.length){reading.highlight?.dispose();activeReading=null;start.disabled=false;stop.disabled=true;status.textContent='Lecture terminée.';return;}const utterance=new API(reading.parts[reading.index++]);reading.utterance=utterance;const tokens=reading.highlight?.locate(utterance.text)||[];reading.highlight?.show(tokens);utterance.onboundary=e=>{if(activeReading!==reading||reading.utterance!==utterance||e.name==='sentence')return;reading.highlight?.show(tokens,e.charIndex);};utterance.lang=CONFIG.locale;utterance.rate=0.70;const voices=synth.getVoices?.()||[];utterance.voice=voices.find(v=>v.voiceURI===preferredReadingVoice())||voices.find(v=>v.lang===CONFIG.locale)||voices.find(v=>v.lang?.startsWith(CONFIG.locale.split('-')[0]))||null;utterance.onend=next;utterance.onerror=()=>{if(activeReading!==reading)return;stopReading();status.textContent='La lecture n’a pas pu continuer. Tu peux réessayer.';};try{synth.speak(utterance);}catch(e){utterance.onerror();}};next();};stop.onclick=()=>{stopReading();status.textContent='Lecture arrêtée.';};}


function sessionLesson(s){if(!s||s.kind==='complete'||s.pathId)return null;if(LESSON_BY_ID[s.originLessonId])return s.originLessonId;const ids=[...new Set((s.questions||[]).map(q=>q.lessonId))];return ids.length===1&&LESSON_BY_ID[ids[0]]?ids[0]:null;}
function lessonForQuestion(id){return QUESTIONS[id]?.lessonId||state.session?.questions.find(q=>q.id===id)?.lessonId;}
function batchSize(){return CONFIG.reviewBatchSize||CONFIG.miniQuizSize;}
function completeIds(){return CONFIG.reviewQuestionIds||CONFIG.finalQuestionIds;}
function startComplete(mode){beginSession(completeIds(),'Quiz final',mode);state.session.kind='complete';state.session.checkpointAck=0;save();renderQuiz();}
function practiceCoverage(mode){const rows=state.history.filter(h=>h.mode===mode).flatMap(h=>h.rows);const s=state.session;if(s&&s.mode===mode)for(let i=0;i<s.choices.length;i++){const q=questionAt(s,i);rows.push({qi:s.ids[i],independent:s.choices[i]===q.a&&!hasHelp(s.meta[i]),questionVersion:q.fingerprint});}const latest=new Map(rows.map(r=>[r.qi,r]));return completeIds().map(id=>({id,label:QUESTIONS[id].practiceLabel||QUESTIONS[id].q,lessonId:QUESTIONS[id].lessonId,status:latest.has(id)?QUESTIONS[id].responseType==='development'?'self':latest.get(id).independent?'alone':'review':'unseen'}));}
function coverageMarkup(mode){const rows=practiceCoverage(mode),seen=rows.filter(r=>r.status!=='unseen').length,alone=rows.filter(r=>r.status==='alone').length;return `<p><b>${seen}/${rows.length}</b> points de pratique abordés · <b>${alone}</b> réussis sans aide au dernier essai dans ce mode.</p><p class="small">Un point abordé n’est pas nécessairement maîtrisé. Les mini-quiz de leçon ne vérifient pas toutes les sous-notions.</p><details><summary>Les points qui restent à pratiquer</summary>${LESSONS.map(l=>{const missing=rows.filter(r=>r.lessonId===l.id&&r.status!=='alone');return missing.length?`<h3>${escapeHTML(l.title)}</h3><ul>${missing.map(r=>`<li>${escapeHTML(r.label)} — ${r.status==='unseen'?'pas encore abordé':r.status==='self'?'autoévaluation faite, à vérifier avec un adulte':'à retravailler'}</li>`).join('')}</ul>`:'';}).join('')||'<p>Tous les points ont été réussis au dernier essai. Reviens un autre jour pour vérifier ce qui reste en mémoire.</p>'}</details>`;}
function renderCheckpoint(){const s=state.session;$('#quiz').innerHTML=`<article class="paper"><h2>Une petite série terminée</h2><p>${s.pos} questions sur ${s.ids.length}. Tu peux continuer ou faire une pause.</p><div id="checkpoint-actions" class="actions"></div></article>`;$('#checkpoint-actions').append(button('Continuer les '+Math.min(batchSize(),s.ids.length-s.pos)+' prochaines questions',()=>{s.checkpointAck=s.pos;save();renderQuiz();focusHeading($('#quiz'));},'primary'),button('Faire une pause',()=>{quizLanding=true;save();renderQuiz();}));}
function finishPartial(){const s=state.session;if(s&&s.choices.length){const partial={...s,label:s.label+' · série interrompue',ids:s.ids.slice(0,s.choices.length),questions:s.questions.slice(0,s.choices.length),meta:s.meta.slice(0,s.choices.length)};saveCompleted(partial);}state.session=null;quizLanding=true;save();quizMenu();}
function quizMenu(){const total=(CONFIG.quizPaths?.[state.pathId]?.entries||completeIds()).length,pending=state.session&&state.session.pos<state.session.ids.length,big=pending&&state.session.kind==='complete';
$('#quiz').innerHTML=`<div class="paper hero"><div class="eyebrow">Les ${DATA.objectives.length} objectifs du fascicule</div><h2>Quiz final</h2>${pending?`<div class="note"><p>${big?'Ton quiz final':'Ton mini-quiz de leçon'} est en pause : ${state.session.choices.length}/${state.session.ids.length} réponses données.</p><button id="resume-quiz" class="primary">${big?'Reprendre le quiz final':'Continuer le mini-quiz'}</button>${big?'<p class="small">Les réponses données seront conservées.</p><button id="end-series">Choisir un nouveau quiz</button>':''}</div>`:''}${!big?`<label for="difficulty">Choisir mon parcours</label><select id="difficulty" class="picker">${Object.entries(CONFIG.quizPaths||{'1':{label:'Quiz',entries:completeIds()}}).map(([id,path])=>`<option value="${escapeHTML(id)}" ${state.pathId===id?'selected':''}>${escapeHTML(path.label)} — ${path.entries.length} questions</option>`).join('')}</select><p>${escapeHTML(CONFIG.quizPaths?.[state.pathId]?.description||'Pratiquer les notions du cours.')}</p><p>${total} questions pour pratiquer les ${DATA.objectives.length} requis. Tu peux faire une pause et reprendre plus tard.</p>${pending?'<p>En commençant le quiz final, tes réponses au mini-quiz seront conservées dans l’historique.</p>':''}<div class="actions"><button id="complete-choice" class="primary">Commencer le quiz</button></div><p class="small">Les mini-quiz restent disponibles à la fin des leçons dans Apprendre.</p>`:''}<details><summary>Les points pratiqués dans ce quiz</summary>${coverageMarkup('practice')}</details><button id="history-open" class="quiet">Voir mon historique</button></div>`;
if(pending){$('#resume-quiz').onclick=()=>{prepareStructuredResume();quizLanding=false;save();renderQuiz();};if(big)$('#end-series').onclick=finishPartial;}
if(!big){$('#difficulty').onchange=e=>{state.pathId=e.target.value;save();quizMenu();};$('#complete-choice').onclick=()=>{if(pending)finishPartial();startPath('practice');};}
$('#history-open').onclick=()=>{show('home');$('#history-details').open=true;$('#history-details').scrollIntoView?.();};}

function quizResult(){const s=state.session,origin=sessionLesson(s),h=saveCompleted(s),c=counts(h),review=h.rows.filter(r=>!r.independent).map(r=>r.qi);$('#quiz').innerHTML=`<div class="paper"><div class="eyebrow">Série terminée</div><h2>Ce que j’ai réussi à faire</h2>${scoreMarkup(h)}<p><b>${c.total?Math.round(c.alone/c.total*100)+' % sans aide dans le site, au premier essai.':'Réponses à développer : autoévaluation, sans note automatique.'}</b></p>${origin?'':coverageMarkup(s.mode)}<p>L’aide n’est pas une faute. Elle montre ce qu’on va reprendre ensemble. Une réussite après un indice ne compte pas comme une réussite autonome.</p><p class="small">Ce bilan décrit l’activité dans le site. Il ne peut pas vérifier l’utilisation d’un autre site ou l’aide d’une autre personne.</p><div id="review-links" class="links"></div><div id="result-actions" class="actions"></div><details><summary>Voir le détail de cette série</summary>${h.rows.map((r,i)=>`<p class="small">${i+1}. ${escapeHTML(THEMES[QUESTIONS[r.qi]?.t||r.topic]||'Question archivée')} : ${r.meta.development?'développement comparé au corrigé (autoévaluation)':r.independent?'sans aide au premier essai':r.correct?'réussie avec aide / nouvel essai':'à revoir'}${r.meta.hints?' · indice':''}${r.meta.tutorial?' · tutoriel':''}${r.meta.lesson?' · leçon consultée':''}${r.meta.external?' · autre aide déclarée':''}${r.meta.errors?' · '+r.meta.errors+' essai(s) incorrect(s)':''}${r.meta.skipped?' · correction consultée':''}</p>`).join('')}</details><p class="small">Pour vérifier ce qui reste en mémoire, reprends quelques questions un autre jour, sans indice. Un adulte peut te demander d’expliquer une réponse avec tes mots.</p></div>`;[...new Set(review.map(lessonForQuestion))].filter(id=>LESSON_BY_ID[id]).forEach(i=>$('#review-links').append(button('Revoir : '+LESSON_BY_ID[i].title,()=>openLesson(i),'quiet')));if(origin){const position=LESSONS.findIndex(l=>l.id===origin),leave=id=>{state.session=null;save();openLesson(id);};if(position<LESSONS.length-1)$('#result-actions').append(button('Leçon suivante →',()=>leave(LESSONS[position+1].id),'primary'));$('#result-actions').append(button('Revoir cette leçon',()=>leave(origin)),button('Retour aux leçons',()=>leave(origin)));return;}$('#result-actions').append(button('Retour au quiz final',()=>{state.session=null;save();renderQuiz();focusHeading($('#quiz'));}),button('Voir mon historique',()=>{show('home');$('#history-details').open=true;}));}
function applyFont(){document.body.classList.toggle('large',state.large);$('#font').setAttribute('aria-pressed',state.large);$('#font').textContent=state.large?'Revenir à la taille habituelle':'Agrandir le texte';}
$('#font').onclick=()=>{state.large=!state.large;applyFont();save();};$('#reset').onclick=()=>{$('#reset-confirm').hidden=false;$('#reset-cancel').focus();};$('#reset-cancel').onclick=()=>{$('#reset-confirm').hidden=true;$('#reset').focus();};$('#reset-yes').onclick=()=>{state=fresh();save();applyFont();$('#reset-confirm').hidden=true;show('home');announce('Progression effacée.');};window.addEventListener?.('pagehide',stopReading);document.addEventListener?.('visibilitychange',()=>{if(document.hidden){stopReading();if(view==='quiz')renderQuiz();}});applyFont();saveNote();show('home',false);

function formulaText(text){return String(text).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/divise(?:e)? par/g,'/').replace(/fois/g,'*').replace(/[÷]/g,'/').replace(/[×]/g,'*').replace(/\s+/g,'').replace(/[’']/g,'');}
function assessFormula(q,text){const n=formulaText(text);if(q.accepted.some(a=>formulaText(a)===n))return 'correct';return q.o.some((o,i)=>i!==q.a&&formulaText(o)===n)?'wrong':'unknown';}
function assessMatching(q,text){const found=[...String(text).toUpperCase().matchAll(/([A-Z])\s*[=:−-]\s*(\d+)/g)];if(found.length!==Object.keys(q.grading.pairs).length||new Set(found.map(x=>x[1])).size!==found.length)return 'unknown';return found.every(x=>q.grading.pairs[x[1]]===x[2])?'correct':'wrong';}
function matchingMarkup(q,choice,answered){const m=q.matching;return `<div class="example"><p>${m.terms.map(t=>escapeHTML(t.id)+'. '+escapeHTML(t.label)).join(' · ')}</p>${m.items.map(item=>`<div style="margin:12px 0"><label for="match-${item.id}">${escapeHTML(item.id)}. ${escapeHTML(item.label)}</label>${choice&&!answered?`<select id="match-${item.id}" class="picker"><option value="">Choisir un terme</option>${m.terms.map(t=>`<option value="${t.id}">${escapeHTML(t.label)}</option>`).join('')}</select>`:''}</div>`).join('')}</div>`;}

function startPath(mode){const path=CONFIG.quizPaths?.[state.pathId];if(!path){startComplete(mode);return;}const oldDifficulty=state.difficulty;const planned=path.entries.map(entry=>{state.difficulty=String(entry.level||1);return {...entry,variantId:entry.variantId||pickVariant(entry.questionId,mode)};});state.difficulty=oldDifficulty;beginSession(planned.map(e=>e.questionId),path.label,mode,false,planned);state.session.kind='complete';state.session.pathId=state.pathId;state.session.pathObjectives=planned.map(e=>e.objectiveId);state.session.slotIds=planned.map(e=>e.slotId);save();renderQuiz();}

function wordEquivalent(expected,actual,g){if(expected===actual)return true;return (g.typoWords||[]).map(normalizeWritten).includes(expected)&&expected.length>=5&&(editOne(expected,actual)||adjacentSwap(expected,actual));}
function phraseEquivalent(q,text){const g=q.grading||{};if(!(g.equivalents||[]).length&&!(g.typoWords||[]).length)return false;let input=softenWritten(text);if((g.equivalents||[]).map(softenWritten).includes(input))return true;for(const prefix of [...(g.answerPrefixes||[])].sort((a,b)=>b.length-a.length)){const p=normalizeWritten(prefix);if(input.startsWith(p+' ')){input=input.slice(p.length+1);break;}}return [...q.accepted,...(g.equivalents||[])].some(answer=>{const words=softenWritten(answer).split(' '),actual=input.split(' ');return words.length===actual.length&&words.every((word,i)=>wordEquivalent(word,actual[i],g));});}
function multiMarkup(q,m,answered){return q.multiSelect.options.map(o=>`<label class="radio ${answered&&q.multiSelect.correctIds.includes(o.id)?'correct':''}"><input type="checkbox" id="multi-${escapeHTML(o.id)}" value="${escapeHTML(o.id)}" ${(m.selectedIds||[]).includes(o.id)?'checked':''} ${answered?'disabled':''}><span>${escapeHTML(o.label)}${answered&&q.multiSelect.correctIds.includes(o.id)?' — ✓ À choisir':''}</span></label>`).join('');}
function submitMulti(q,m){const ids=q.multiSelect.options.filter(o=>$('#multi-'+o.id).checked).map(o=>o.id);if(!ids.length){$('#choice-help').textContent='Coche les réponses que tu choisis.';return;}m.selectedIds=ids;const correct=ids.length===q.multiSelect.correctIds.length&&ids.every(id=>q.multiSelect.correctIds.includes(id));tryChoice(correct?q.a:(q.a+1)%q.o.length);if(!correct&&state.session.choices.length===state.session.pos){$('#choice-help').textContent='Ta sélection est à compléter ou à corriger. Tu peux réessayer; ce nouvel essai sera indiqué dans le bilan.';}}
function multiFeedback(q,m){const chosen=m.selectedIds||[],missing=q.multiSelect.options.filter(o=>q.multiSelect.correctIds.includes(o.id)&&!chosen.includes(o.id)),extra=q.multiSelect.options.filter(o=>chosen.includes(o.id)&&!q.multiSelect.correctIds.includes(o.id));return (missing.length?'<p><b>À ajouter :</b> '+missing.map(o=>escapeHTML(o.label)).join(', ')+'.</p>':'')+(extra.length?'<p><b>À retirer :</b> '+extra.map(o=>escapeHTML(o.label)).join(', ')+'.</p>':'');}

function adjacentSwap(a,b){if(a.length!==b.length)return false;const diffs=[];for(let i=0;i<a.length;i++)if(a[i]!==b[i])diffs.push(i);return diffs.length===2&&diffs[1]===diffs[0]+1&&a[diffs[0]]===b[diffs[1]]&&a[diffs[1]]===b[diffs[0]];}

function usesChoices(s,q){if(q.responseType==='development')return false;return s.mode==='practice'?q.responseType!=='number':s.mode==='choice';}
function assessNumber(q,text){const expected=q.numericAnswer;if(!expected)return 'unknown';const match=String(text).trim().match(/^([+-]?(?:\d+(?:[.,]\d*)?|[.,]\d+))\s*(.*?)$/);if(!match)return 'unknown';const value=Number(match[1].replace(',','.')),unit=match[2].toLowerCase().replace(/\s/g,'');if(unit&&!(expected.units||[]).some(u=>u.toLowerCase().replace(/\s/g,'')===unit))return 'unknown';return Number.isFinite(value)&&Math.abs(value-expected.value)<=Number.EPSILON*Math.max(1,Math.abs(expected.value))*8?'correct':'wrong';}
function prepareStructuredResume(){const s=state.session;if(!s||s.mode!=='written')return;s.mode='practice';s.questions=s.questions.map(q=>{const current=findVariant(q.id,q.variantId);return {...q,responseType:current.responseType==='number'&&current.writtenPrompt===q.writtenPrompt?'number':'choice',numericAnswer:current.writtenPrompt===q.writtenPrompt?current.numericAnswer:undefined};});}


/* Extensions génériques : lecture des leçons et réponse développée autoévaluée. */
function plainSpeech(text){return String(text||'').replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,' et ').replace(/\s+/g,' ').trim();}
function spokenText(text){const replacements=CONFIG.speechReplacements||{},keys=Object.keys(replacements).sort((a,b)=>b.length-a.length);if(!keys.length)return plainSpeech(text);const escaped=keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));const re=new RegExp('(?<![\\p{L}\\p{N}])(?:'+escaped.join('|')+')(?![\\p{L}\\p{N}])','gu');return plainSpeech(text).replace(re,word=>replacements[word]);}
function renderDevelopment(s,q,m,answered){
 m.development=true;
 const compared=m.selfReview==='opened'||answered;
 $('#quiz').innerHTML=`<article class="paper"><div class="row spread"><span class="pill">${escapeHTML(sessionLabel(s))}</span><span class="small">Question ${s.pos+1} sur ${s.ids.length}</span></div><progress aria-label="Questions terminées" max="${s.ids.length}" value="${s.choices.length}"></progress><div class="actions"><button id="read-question" type="button">🔊 Lire la question</button><button id="stop-reading" type="button" disabled>Arrêter la lecture</button></div><p id="reading-status" role="status" class="small"></p><h2>${escapeHTML(q.writtenPrompt)}</h2>${renderResource(q.promptResource)}<p>Explique avec tes mots. Tu peux écrire ici, ou préparer ta réponse sur papier et l’expliquer à un adulte.</p><label for="development-answer">Ma réponse ou mes étapes</label><textarea id="development-answer" rows="5" style="width:100%;font:inherit;padding:12px;border:2px solid var(--line);border-radius:12px" ${answered||compared?'readonly':''}>${escapeHTML(m.developmentText||'')}</textarea><p class="small">Cette réponse est à comparer au corrigé. Elle ne reçoit pas de note automatique.</p>${!compared?'<div class="actions"><button id="compare-development" class="primary">Comparer au corrigé</button><button id="paper-development">J’ai répondu sur papier ou à voix haute</button><button id="development-hint">Un indice</button><button id="development-skip" class="quiet">Je ne sais pas — voir l’explication</button></div>':''}<p id="development-help" role="status">${m.hints?escapeHTML(q.hint):''}</p><div id="feedback" tabindex="-1" ${compared?'':'hidden'} class="feedback"><h3>Je compare mon raisonnement</h3><p>${compared?escapeHTML(q.e):''}</p>${compared?correctionPicture(q.id,q):''}${compared?(q.rubric||[]).map((item,i)=>`<label class="radio"><input type="checkbox" id="rubric-${i}" ${(m.rubricChecked||[]).includes(i)?'checked':''} ${answered?'disabled':''}><span>${escapeHTML(item)}</span></label>`).join(''):''}${compared?'<p class="small">Coche seulement les points présents dans ta réponse de départ. Un adulte peut t’aider à comparer. Cette autoévaluation reste distincte des réponses corrigées automatiquement.</p>':''}</div><div id="development-actions" class="actions"></div><button id="development-back" class="quiet">${sessionLesson(s)?'Retour à la leçon':'Retour au menu du quiz final'}</button></article>`;
 setupReading(s,q);if(compared)setupCorrectionReading(s,q);
 $('#development-answer').oninput=e=>{m.developmentText=e.target.value;save();};
 $('#development-back').onclick=()=>{stopReading();const l=sessionLesson(s);if(l)openLesson(l);else{quizLanding=true;renderQuiz();}};
 if(!compared){const compare=allowEmpty=>{const text=$('#development-answer').value.trim();if(!text&&!allowEmpty){$('#development-help').textContent='Écris quelques mots, ou indique que tu as répondu sur papier ou à voix haute.';return;}m.developmentText=text;m.selfReview='opened';save();stopReading();renderQuiz();$('#feedback').focus();};$('#compare-development').onclick=()=>compare(false);$('#paper-development').onclick=()=>compare(true);$('#development-skip').onclick=()=>{m.skipped=true;compare(true);};$('#development-hint').onclick=()=>{m.hints=1;save();$('#development-help').textContent=q.hint;};}
 else if(!answered){for(let i=0;i<(q.rubric||[]).length;i++)$('#rubric-'+i).onchange=()=>{m.rubricChecked=q.rubric.map((_,j)=>j).filter(j=>$('#rubric-'+j).checked);save();};$('#development-actions').append(button('J’ai comparé ma réponse',()=>{m.selfReview=(m.rubricChecked||[]).length===q.rubric.length?'complete':'review';stopReading();finishChoice(-1);},'primary'));}
 else{$('#development-actions').append(button(s.pos+1===s.ids.length?'Voir mon bilan':'Question suivante →',()=>{stopReading();s.pos++;save();renderQuiz();focusHeading($('#quiz'));},'primary'),button('Revoir la leçon',()=>openLesson(q.lessonId)));}
}

function preferredReadingVoice(){try{return localStorage.getItem('ma-revision:reading-voice-v2')||'';}catch(e){return '';}}
function setupVoiceChoice(){
 const select=$('#reading-voice'),note=$('#reading-voice-note'),synth=window.speechSynthesis;
 if(!select)return;
 const refresh=()=>{
  const voices=(synth?.getVoices?.()||[]).filter(v=>/^fr(?:-|_)/i.test(v.lang)||v.lang==='fr');
  select.innerHTML='<option value="">Automatique</option>'+voices.map(v=>'<option value="'+escapeHTML(v.voiceURI)+'">'+escapeHTML(v.name+' — '+v.lang)+'</option>').join('');
  const preferred=preferredReadingVoice();select.value=voices.some(v=>v.voiceURI===preferred)?preferred:'';
  select.disabled=!synth||!voices.length;
  note.textContent=!synth?'La lecture vocale n’est pas disponible dans ce navigateur.':voices.length?'Choisis une voix, puis utilise un bouton Lire pour l’écouter. Ce choix reste sur cet appareil.':'Les voix françaises disponibles dépendent de cet appareil. La voix automatique reste utilisée.';
 };
 select.onchange=()=>{stopReading();try{localStorage.setItem('ma-revision:reading-voice-v2',select.value);}catch(e){};announce('Voix choisie. Appuie sur Lire pour l’écouter.');};
 refresh();synth?.addEventListener?.('voiceschanged',refresh);
}
setupVoiceChoice();
